import {FIELDING_KEYS,ensureThrowing} from './fielding.js';
import {legacyHonors} from './awards.js';
import {migrateProfile} from './profile.js';
import {CONFIG,STAGES,ABILITIES,SCHOOLS,MIDDLE,TRAINING} from './data.js';
import {migrateCareer} from './lifecycle.js';
import {RAW} from './stats.js';
import {migrateTraits,PERSONALITIES} from './personality.js';
// Validation only. Game data is never persisted.
export function validate(s){if(!s||s.version!==CONFIG.version||!STAGES[s.stage]||!s.player||!['pitcher','batter'].includes(s.player.role)||typeof s.player.name!=='string'||s.player.name.length>24)throw Error('このセーブデータは読み込めません。');for(const k of ['year','age','grade','period','seed','scout','salary','totalSalary','proYears'])if(!Number.isFinite(s[k])||s[k]<0)throw Error('数値データが破損しています。');if(!TRAINING.some(t=>t.id===s.training)||s.period>2||s.grade<1||typeof s.retired!=='boolean')throw Error('進行データが破損しています。');if(s.stage==='high'&&!SCHOOLS.some(e=>e.id===s.environmentId)||s.stage==='middle'&&!MIDDLE.some(e=>e.id===s.environmentId))throw Error('所属データが見つかりません。');ensureThrowing(s);for(const k of Object.keys(ABILITIES))if(!Number.isFinite(s.player.abilities?.[k])||s.player.abilities[k]<0||s.player.abilities[k]>99)throw Error('能力データが破損しています。');for(const k of ['talent','peakAge'])if(!Number.isFinite(s.player[k]))throw Error('選手データが破損しています。');for(const k of ['records','tournaments','drafts','nationalHistory','awards','contracts','teams','timeline','news','periodResults'])if(!Array.isArray(s[k]))throw Error('履歴データが破損しています。');const stats=[s.current,...s.records.map(r=>r.stats),...s.tournaments.map(r=>r.stats),...s.nationalHistory.filter(r=>r.selected&&r.participated!==false).map(r=>r.stats),...s.periodResults.map(r=>r.stats),...s.records.flatMap(r=>r.levels?Object.values(r.levels):[]),...(s.currentLevels?Object.values(s.currentLevels):[])];for(const st of stats){if(st){for(const k of FIELDING_KEYS)if(st[k]===undefined){st[k]=0;st.fieldingKnown=false;}st.saves??=0;st.holds??=0;for(const k of ['rispAb','rispHits','allowedHbp','runsAllowed','allowedHr'])if(st[k]===undefined){st[k]=0;st.detailsKnown=false;}}for(const k of ['war','defenseRuns'])if(st?.[k]!==undefined&&!Number.isFinite(st[k]))throw Error('貢献度データが破損しています。');}for(const st of stats)for(const k of RAW)if(!Number.isFinite(st?.[k])||st[k]<0)throw Error('成績データが破損しています。');if(s.pending&&!['middle','high','career'].includes(s.pending.type))throw Error('進路データが破損しています。');if(s.pending?.type==='career'&&(!s.pending.draft||!['支配下','育成','指名なし'].includes(s.pending.draft.type)))throw Error('ドラフトデータが破損しています。');migrateTraits(s);migrateCareer(s);migrateProfile(s);if(s.retired)legacyHonors(s);if(!PERSONALITIES.some(p=>p.id===s.player.personality)||!Array.isArray(s.moves)||typeof s.marketAttempts!=='object'||s.marketAttempts===null)throw Error('選手特性・移籍データが破損しています。');for(const value of Object.values(s.player.potential))if(!Number.isFinite(value)||value<5||value>99)throw Error('成長データが破損しています。');return s;}
